import{c as a,Q as e,j as s,m as l}from"./chunks/framework.DOi4mjdC.js";const d=JSON.parse('{"title":"asc_set_vector_mask","description":"","frontmatter":{},"headers":[{"level":1,"title":"asc_set_vector_mask","slug":"asc_set_vector_mask"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"流水类型","slug":"流水类型"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/c_api/vector_compute/asc_set_vector_mask.md","filePath":"api/SIMD-API/c_api/vector_compute/asc_set_vector_mask.md"}'),i={name:"api/SIMD-API/c_api/vector_compute/asc_set_vector_mask.md"};function r(h,t,o,n,_,c){return e(),s("div",null,[...t[0]||(t[0]=[l('<h1 id="asc-set-vector-mask" tabindex="-1">asc_set_vector_mask <a class="header-anchor" href="#asc-set-vector-mask" aria-label="Permalink to &quot;asc_set_vector_mask&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">产品</th><th style="text-align:center;">是否支持</th></tr></thead><tbody><tr><td style="text-align:left;">&lt;term&gt;Atlas A3 训练系列产品/Atlas A3 推理系列产品&lt;/term&gt;</td><td style="text-align:center;">√</td></tr><tr><td style="text-align:left;">&lt;term&gt;Atlas A2 训练系列产品/Atlas A2 推理系列产品&lt;/term&gt;</td><td style="text-align:center;">√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>某些矢量计算接口需要提前设置Mask，提示哪些数据需要参与计算。 该API用于设置Mask，使用前需要先调用<a href="./asc_set_mask_count.html">asc_set_mask_count</a>和<a href="./asc_set_mask_norm.html">asc_set_mask_norm</a>设置Mask模式。在不同的模式下Mask的含义如下：</p><ul><li>Normal模式用于高维切分计算类API。该模式下，Mask参数用来控制单次迭代内参与计算的元素。可以按位控制哪些元素参与计算：bit位的值为1表示参与计算，0表示不参与。分为mask1(高位Mask)和mask0（低位Mask）。参数取值范围和操作数的数据类型有关，数据类型不同，每次迭代内能够处理的元素个数最大值不同。当操作数为16位时，mask0，mask1∈[0, 2^64-1]，并且不同时为0；当操作数为32位时，mask1为0，mask0∈(0, 2^64-1]；当操作数为64位时，mask1为0，mask0∈(0, 2^32-1]。</li><li>Counter模式用于前n个数据计算类API。该模式下，Mask参数用于控制整个计算过程中参与计算的元素个数。前n个数据计算类接口中已经实现了Normal模式和Counter模式的转换，用户不需要进行自行设置。</li></ul><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">__aicore__ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">inline</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> asc_set_vector_mask</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint64_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> mask1, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint64_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> mask0)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>mask1</td><td>输入</td><td>Normal模式：高位mask值。&lt;br&gt;Counter模式：需要置0，本入参不生效。</td></tr><tr><td>mask0</td><td>输入</td><td>Normal模式：低位mask值。&lt;br&gt;Counter模式：整个矢量计算过程中，参与计算的元素个数。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="流水类型" tabindex="-1">流水类型 <a class="header-anchor" href="#流水类型" aria-label="Permalink to &quot;流水类型&quot;">​</a></h2><p>PIPE_S</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>需先调用<a href="./asc_set_mask_count.html">asc_set_mask_count</a>或<a href="./asc_set_mask_norm.html">asc_set_mask_norm</a>设置Mask模式。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>请参考<a href="./asc_set_mask_count.html#调用示例">asc_set_mask_count</a>或<a href="./asc_set_mask_norm.html#调用示例">asc_set_mask_norm</a>。</p>',18)])])}const m=a(i,[["render",r]]);export{d as __pageData,m as default};
